#include <algorithm>
#include <cassert>
#include <climits>
#include <iostream>
#include <vector>
struct Node { int value; int left; int right; };
// 유효한 트리의 인덱스를 받는다. 경계가 없다는 사실은 별도 bool로 표현한다.
bool check(const std::vector<Node>& a, int i, bool hasLo, int lo, bool hasHi, int hi) {
    if (i == -1) return true;
    const Node& n = a[static_cast<std::size_t>(i)];
    if ((hasLo && n.value <= lo) || (hasHi && n.value >= hi)) return false;
    return check(a, n.left, hasLo, lo, true, n.value)
        && check(a, n.right, true, n.value, hasHi, hi);
}
bool valid(const std::vector<Node>& a, int root) {
    return check(a, root, false, 0, false, 0);
}
// 독립 비교 기준: 중위 순회 결과가 엄격히 증가하는지 확인한다.
void inorder(const std::vector<Node>& a, int i, std::vector<int>& values) {
    if (i == -1) return;
    const Node& n = a[static_cast<std::size_t>(i)];
    inorder(a, n.left, values); values.push_back(n.value); inorder(a, n.right, values);
}
bool reference(const std::vector<Node>& a, int root) {
    std::vector<int> v; inorder(a, root, v);
    for (std::size_t i = 1; i < v.size(); ++i) if (v[i - 1] >= v[i]) return false;
    return true;
}
int main() {
    // 세 가지 모양에 정수 세 종류를 전부 배정하여 비교한다.
    const std::vector<std::vector<Node> > shapes = {
        {{0,1,2},{0,3,4},{0,-1,-1},{0,-1,-1},{0,-1,-1}},
        {{0,-1,1},{0,-1,2},{0,-1,3},{0,-1,4},{0,-1,-1}},
        {{0,1,-1},{0,2,-1},{0,3,-1},{0,4,-1},{0,-1,-1}}
    };
    int tested = 0;
    for (const auto& shape : shapes) for (int mask = 0; mask < 243; ++mask) {
        auto a = shape; int x = mask;
        for (auto& n : a) { n.value = x % 3 - 1; x /= 3; }
        assert(valid(a,0) == reference(a,0)); ++tested;
    }
    // 다섯 개의 서로 다른 값을 순열로 배정하여 참/거짓 양쪽 경로를 확인한다.
    int distinctCases = 0, accepted = 0;
    for (const auto& shape : shapes) {
        std::vector<int> values = {-2,-1,0,1,2};
        do {
            auto a = shape;
            for (std::size_t i=0;i<a.size();++i) a[i].value=values[i];
            const bool answer=valid(a,0);
            assert(answer==reference(a,0));
            if(answer) ++accepted;
            ++distinctCases;
        } while(std::next_permutation(values.begin(),values.end()));
    }
    assert(accepted==3); // 모양마다 정확히 한 가지 값 배정만 올바르다.
    assert(valid({{2,1,2},{0,3,4},{3,-1,-1},{-1,-1,-1},{1,-1,-1}},0));
    assert(valid({{0,-1,1},{1,-1,2},{2,-1,3},{3,-1,4},{4,-1,-1}},0));
    assert(valid({{4,1,-1},{3,2,-1},{2,3,-1},{1,4,-1},{0,-1,-1}},0));
    assert(!valid({{2,1,2},{0,3,4},{3,-1,-1},{-1,-1,-1},{4,-1,-1}},0));
    assert(valid({},-1));
    assert(valid({{INT_MIN,-1,1},{INT_MAX,-1,-1}},0));
    assert(!valid({{10,1,2},{5,-1,3},{15,-1,-1},{12,-1,-1}},0));
    assert(!valid({{1,-1,1},{1,-1,-1}},0));
    std::cout << "bounds reference cases: " << tested << "; distinct permutations: " << distinctCases << "; valid assignments: " << accepted << "; empty/extreme/ancestor/duplicate passed\n";
}
